# n: (tema, veredicto "V/F por afirmacion", [razones por afirmacion], nota opcional)
# Veredictos de memoria, contrastados con Saladin (Morfo) y Calvo (Biologia Celular) en
# examenes pasados/MEDICINA/LIBROS DE MEDICINA/_TEXTO_LITERAL_VERIFICADO/ solo donde la nota o la razon lo dice.
# En Q84 ("es incorrecto") la V marca la afirmacion incorrecta, que es la que pide el enunciado.
# Q95, Q97 y Q100: la facultad acepto "A o C"; el veredicto propio (VFV) no tiene letra en la clave de tres
# afirmaciones (dos verdaderas), asi que el generador las manda a `faltantes`.
D = {}
def q(n, tema, v, razones, nota=None): D[n] = (tema, v, razones, nota)

q(1,"via-tectoespinal","FV",["El control fino de las extremidades lo da la vía corticoespinal, no la tectoespinal.","La vía tectoespinal media el giro reflejo de la cabeza ante estímulos visuales y auditivos."])
q(2,"hormonas-hipofisarias-e-hipotalamicas","FV",["La folitropina (FSH) es una hormona de la adenohipófisis; no se origina en los riñones.","La corticoliberina (CRH) es una hormona hipotalámica."])
q(3,"musculos-oblicuos-del-ojo","VV",["El oblicuo superior pasa por la tróclea, un anillo de fibrocartílago.","El oblicuo inferior va de la pared medial de la órbita a la cara inferolateral del globo ocular."])
q(4,"neuroglia","FF",["La microglia deriva de monocitos, no de linfocitos.","Los ependimocitos se parecen a un epitelio cúbico, no a uno pavimentoso."])
q(5,"proteinas-plasmaticas","FV",["La albúmina es la proteína plasmática más pequeña y abundante, no la más grande.","Las globulinas se dividen en alfa, beta y gamma, de menor a mayor peso molecular."])
q(6,"cornea-y-cuerpo-ciliar","FV",["La córnea tiene un epitelio pavimentoso estratificado DELGADO por delante (Saladin, órganos de los sentidos); la afirmación dice «grueso».","El cuerpo ciliar forma un anillo muscular alrededor del cristalino, sostiene el iris y el cristalino y secreta humor acuoso (Saladin, órganos de los sentidos)."])
q(7,"electrocardiograma","VF",["La onda P corresponde a la despolarización de las aurículas por la señal del nódulo SA.","El complejo QRS corresponde a la despolarización de los ventrículos, no del miocardio auricular."])
q(8,"sonoridad-y-escala-de-decibeles","FV",["La sonoridad es la percepción de la energía o INTENSIDAD del sonido, no de su «longitud» (Saladin, órganos de los sentidos).","El umbral de audición es 0 dB y cada 10 dB equivalen a una intensidad diez veces mayor."])
q(9,"vasopresina-y-lutropina","VF",["La vasopresina (ADH) aumenta la retención de agua en el riñón y reduce el volumen de orina.","La lutropina estimula al cuerpo lúteo para que secrete progesterona, no estrógenos como dice la afirmación (Saladin, sistema endocrino)."])
q(10,"membrana-del-eritrocito","VF",["Los glucolípidos de la superficie externa determinan el grupo sanguíneo.","La espectrina y la actina son proteínas del citoesqueleto que van en la cara INTERNA de la membrana."])
q(11,"venas-suprarrenal-y-gonadal","VF",["La vena suprarrenal derecha desemboca directamente en la vena cava inferior.","La vena gonadal izquierda desemboca en la vena renal izquierda, no directo en la cava."])
q(12,"sistema-nervioso-autonomo","FV",["Sin el vago el corazón late a su ritmo intrínseco, cercano a 100 latidos por minuto, no a 70.","La pérdida del tono simpático puede bajar la presión de forma tan brusca que provoque choque."])
q(13,"fibras-del-dolor","VF",["Las fibras mielínicas conducen más rápido y producen el dolor rápido.","Las fibras amielínicas son las más lentas y producen el dolor lento, pero la velocidad que cita la afirmación no corresponde."])
q(14,"nervios-de-la-mano","FV",["El aductor del pulgar lo inerva el nervio cubital, no el mediano.","El nervio cubital inerva los músculos hipotenares."])
q(15,"receptores-sensitivos","FV",["Los receptores transmiten modalidad, ubicación, intensidad y duración; la afirmación escribe «modulación», que no es una de las cuatro.","Una sola neurona sensitiva del tacto puede abarcar un área de piel amplia, de hasta unos centímetros de diámetro."])
q(16,"corte-medial-del-encefalo","FV",["El cuarto ventrículo está entre el tronco encefálico y el cerebelo, no entre el diencéfalo y el cerebelo.","La glándula pineal (epitálamo) queda por detrás del tálamo."])
q(17,"metabolismo-del-hierro","VF",["La gastroferrina transporta Fe2+ al intestino delgado y lo libera para su reabsorción (Saladin, sangre).","En el hígado la transferrina libera Fe2+ (no Fe3+) para almacenarlo como ferritina (Saladin, sangre)."])
q(18,"asta-lateral-de-la-medula","FF",["El asta lateral va de T1 a L2, no hasta L3.","Los axones simpáticos salen por la raíz anterior junto con fibras eferentes somáticas, no aferentes."])
q(19,"velocidad-de-conduccion-nerviosa","FV",["Las fibras mielínicas del mismo tamaño conducen mucho más rápido que lo que dice la afirmación; la mielina acelera la conducción.","Las fibras mielínicas de mayor calibre alcanzan velocidades de unos 120 m/s."])
q(20,"plexo-cervical","VF",["Los ramos anteriores de C3, C4 y C5 forman el nervio frénico, que inerva el diafragma.","El nervio occipital mayor proviene del ramo posterior de C2, no de ramos anteriores."])
q(21,"tirotropina","VV",["La tirotropina (TSH) estimula a la tiroides para secretar hormona tiroidea.","La hormona tiroidea retroalimenta negativamente a la hipófisis e inhibe la TSH."])
q(22,"saculo-y-utriculo","VF",["La mácula sacular está casi vertical en la pared del sáculo y la utricular casi horizontal en el piso del utrículo (Saladin, órganos de los sentidos).","Cada célula pilosa de la mácula tiene entre 40 y 70 estereocilios y un cinetocilio (Saladin); la cifra «20 a 40» no coincide."])
q(23,"hemoglobina-fetal","FV",["La hemoglobina fetal tiene dos cadenas gamma en lugar de beta; la afirmación lo invierte.","La HbF fija el oxígeno con más afinidad que la HbA, y por eso el feto lo toma de la sangre materna."])
q(24,"causas-de-anemia","FV",["La anemia perniciosa se debe a falta de factor intrínseco y mala absorción de vitamina B12, no de B3.","La insuficiencia renal reduce la secreción de EPO y produce anemia."])
q(25,"corte-horizontal-del-cerebro","VF",["El tercer ventrículo es medial al tálamo.","El núcleo caudado es lateral al ventrículo lateral, no medial."])
q(26,"micro-arn","FF",["Los micro-ARN se unen por complementariedad al ARN mensajero, no al ARN de transferencia.","Los precursores de los micro-ARN los transcribe la ARN polimerasa (II), no la ADN polimerasa."])
q(27,"adn-mitocondrial","VF",["La neuropatía óptica hereditaria de Leber es una enfermedad por mutación puntual del ADN mitocondrial.","Las mutaciones citadas (3460, 11778, 14484) son las de la neuropatía de Leber, no las de la epilepsia mioclónica con fibras rojas rotas."])
q(28,"nucleolo","VV",["La nucleolina y la nucleofosmina contribuyen a la intensa tinción del nucléolo.","Los snoARN C/D guían la metilación 2'-O del pre-ARNr y se unen a la fibrilarina."])
q(29,"alfa-amanitina","FF",["La α-amanitina es un octapéptido cíclico, no un tetrapéptido, e inhibe sobre todo a la ARN polimerasa II.","La α-amanitina inhibe una ARN polimerasa, no una ADN polimerasa."])
q(30,"filamina","VF",["La filamina entrecruza microfilamentos de actina formando redes ortogonales (Calvo, citoesqueleto).","Sin filamina el citoplasma tiende al estado sol; por tanto la filamina favorece el estado gel (Calvo, citoesqueleto)."])
q(31,"sintesis-de-insulina","FF",["La insulina se traduce en ribosomas del retículo endoplasmático rugoso, no en el Golgi.","La proinsulina pasa del RER al Golgi y de ahí a gránulos de secreción, no al REL."])
q(32,"epigenetica-y-cancer","VV",["La decitabina es un análogo de citidina desmetilante usado en el síndrome mielodisplásico.","La hipermetilación del promotor de p16 silencia este supresor tumoral y favorece el crecimiento descontrolado."])
q(33,"cadena-de-transporte-electronico","VV",["El complejo V (ATP sintasa) sintetiza el ATP.","El ADP se forma sobre todo en el citoplasma al gastarse el ATP y entra a la mitocondria."])
q(34,"cuerpos-de-cajal","VV",["Los cuerpos de Cajal intervienen en la biogénesis, maduración y reciclaje de las snRNP.","También participan en el procesamiento del ARNm de histonas y en el mantenimiento de los telómeros."])
q(35,"tipos-de-arn","FV",["El ARN mensajero lleva la información del ADN (no «del ARN») desde el núcleo a los ribosomas.","El ARN de transferencia lleva los aminoácidos a los ribosomas para la síntesis de proteínas."])
q(36,"o-glucosilacion","FV",["La O-glucosilación ocurre sobre todo en el aparato de Golgi, no de modo exclusivo en el REL.","En la O-glucosilación los azúcares se unen al OH de serina, treonina e hidroxilisina."])
q(37,"snrnp-y-smn","FF",["Los cinco ARN nucleares pequeños del espliceosoma son U1, U2, U4, U5 y U6; la afirmación incluye U3 y U7 (Calvo, ARN).","La clave oficial da esta afirmación como falsa (mira la nota de revisión pendiente, porque el libro de la gestión parece decir lo contrario)."],
  "Revisión pendiente: la clave oficial marca D (ambas falsas). Calvo (Biología Celular, Tema 8, línea 61) dice que la proteína SMN es un componente esencial en la maduración de las snRNP y se localiza en el citoplasma y en los cuerpos de Cajal, por lo que la afirmación 2 sería verdadera y la letra sería B.")
q(38,"glutation","VF",["La glutatión peroxidasa es una selenoenzima.","La glutatión reductasa regenera GSH a partir de GSSG; la afirmación invierte el sentido."])
q(39,"analisis-citogenetico","VV",["La fitohemaglutinina estimula la división de los linfocitos en cultivo.","La colchicina desorganiza el huso y detiene las células en metafase, lo que aumenta el índice mitótico."])
q(40,"inhibidores-de-la-transcripcion","FF",["La rifampicina inhibe la ARN polimerasa bacteriana y no actúa igual en células eucariotas.","La actinomicina D se intercala en el ADN y bloquea la transcripción; no se une a una subunidad de la ARN polimerasa bacteriana."])
q(41,"muestreo-cualitativo","VV",["El muestreo de casos extremos selecciona situaciones inusuales, como éxitos o fracasos rotundos.","La bola de nieve parte de informantes iniciales que recomiendan a otros participantes."])
q(42,"disenos-de-investigacion-cualitativa","FF",["Los ensayos clínicos controlados son un diseño cuantitativo experimental, no cualitativo.","Los diseños cualitativos habituales son el narrativo, el fenomenológico, el etnográfico, el de teoría fundamentada y la investigación-acción; los «cartográficos» no figuran entre ellos."],
  "Nota: esta pregunta es de Educación en Salud e Investigación; no hay libro de la gestión en el repo para contrastarla.")
q(43,"muestreo-sistematico","FV",["El punto de arranque del muestreo sistemático se elige al azar dentro del primer intervalo; no tiene que ser el número 1.","El intervalo de selección es N dividido entre n."])
q(44,"muestreo-aleatorio-y-sistematico","VV",["En el muestreo aleatorio simple cada unidad tiene probabilidad equitativa y conocida.","El muestreo sistemático puede sesgarse si el intervalo coincide con un patrón cíclico de la población."],
  "Nota: la cartilla original marcaba B, pero la facultad publicó una corrección a C, que es la clave que vale aquí.")
q(45,"muestra-cualitativa","FF",["En un estudio cualitativo la muestra depende de los objetivos y del fenómeno, no del interés de los lectores.","El estudio cualitativo usa muestreo intencional, no probabilístico."])
q(46,"conceptos-variables-e-indicadores","VF",["Los conceptos son construcciones lógicas abstractas que no existen fuera del marco de referencia.","Una variable compleja se define por dimensiones e indicadores; no basta un solo indicador simple."],
  "Nota: la cartilla original marcaba B, pero la facultad publicó una corrección a A, que es la clave que vale aquí.")
q(47,"muestreo-cualitativo-intencional","VF",["El muestreo de máxima variabilidad incluye deliberadamente las distintas posibilidades de las variables importantes.","Los casos críticos son los de mayor impacto sobre el sistema, no los rutinarios."])
q(48,"tamano-de-muestra","FV",["Si los fenómenos son muy homogéneos se necesita una muestra más pequeña, no más grande.","Con la fórmula de cruce de variables, cuanto menor es la proporción esperada, mayor debe ser la muestra."])
q(49,"sesgo-de-muestreo","VF",["El sesgo de muestreo ocurre cuando un sector de la población queda sobre o subrepresentado.","Usar voluntarios introduce sesgo de autoselección; no lo elimina."])
q(50,"escala-nominal","FV",["En la escala nominal los números no expresan orden ni magnitud.","En la escala nominal los números solo categorizan o identifican."],
  "Nota: en el original la afirmación 2 termina en «sea mayor», sin completarse.")
q(51,"glicina","FFV",["La unión neuromuscular usa acetilcolina, no glicina.","Hipotálamo y tálamo no son el sitio característico de la glicina.","La glicina es un neurotransmisor inhibidor del encéfalo, la médula espinal y la retina."])
q(52,"conduccion-en-fibras-mielinicas","VFF",["Los canales de compuerta de voltaje son escasos en los internódulos cubiertos de mielina.","Por esa razón los potenciales de acción NO se generan en los internódulos.","La mielina aumenta la separación entre los líquidos intracelular y extracelular, no la disminuye."])
q(53,"defectos-de-refraccion","FFV",["En la hipermetropía el globo ocular es demasiado corto.","El astigmatismo se debe a una curvatura irregular de la córnea o el cristalino.","En la miopía el globo ocular es demasiado largo."])
q(54,"retorno-venoso-pulmonar","VFF",["Las venas pulmonares llevan la sangre de los pulmones a la aurícula izquierda.","El seno coronario desemboca en la aurícula derecha.","El tronco pulmonar lleva sangre del ventrículo derecho a los pulmones."])
q(55,"venas-del-corazon","FFF",["La vena cardiaca media va por el surco interventricular posterior; la marginal izquierda no desemboca en ella (Saladin, corazón).","Saladin (corazón) describe la vena marginal izquierda subiendo hacia el margen izquierdo y vaciándose en el seno coronario, no en la vena cardiaca mayor.","La vena interventricular posterior es la vena cardiaca media; la marginal izquierda no desemboca en ella."])
q(56,"organo-de-corti","VVV",["El órgano de Corti tiene un epitelio de células pilosas y células de soporte.","La membrana tectoria gelatinosa cubre las puntas de los estereocilios.","El órgano de Corti recorre en espiral toda la cóclea con una fila de células pilosas internas y tres de externas, cuatro en total."])
q(57,"histologia-de-la-hipofisis","VVV",["El lóbulo anterior contiene células basófilas.","Los tirotropos son células basófilas del lóbulo anterior.","El lóbulo posterior es tejido nervioso (neurohipófisis)."])
q(58,"basofilos","FFV",["Los monocitos no son el leucocito que aumenta en esa lista de enfermedades.","Los eosinófilos aumentan en alergias y parasitosis, no en esa lista.","Los basófilos aumentan en varicela, sinusitis, diabetes mellitus, mixedema y policitemia."])
q(59,"centros-del-aprendizaje-y-las-emociones","VVV",["La corteza prefrontal medial participa en el aprendizaje y las emociones.","El cuerpo mamilar y los núcleos talámicos participan en la memoria y las emociones.","El hipocampo y la amígdala son centros clave del aprendizaje y las emociones."])
q(60,"ondas-cerebrales","VFF",["Las ondas alfa son de 8 a 13 Hz y predominan en el área parietooccipital.","Las ondas de 14 a 30 Hz son las beta, no las zeta.","Las ondas de 4 a 7 Hz son las zeta; las beta son de 14 a 30 Hz."])
q(61,"inervacion-autonoma-del-facial","FVF",["Las glándulas gustativas no son las que recibe el facial en esa lista.","El nervio facial envía fibras autónomas a las glándulas salivales submandibular y sublingual.","La parótida recibe fibras del nervio glosofaríngeo, no del facial."])
q(62,"presion-arterial-media","FFV",["115 mmHg no corresponde: la presión media es la diastólica más un tercio de la presión de pulso.","108 mmHg no corresponde con ese cálculo.","Con 85 + (130 − 85) / 3 = 100 mmHg, la presión arterial media es de casi 100 mmHg."])
q(63,"neurotransmisores-y-apetito","FFV",["La dopamina no es el neurotransmisor que suprime el apetito en esta lista.","La sustancia P participa en el dolor, no en suprimir el apetito.","La colecistocinina produce saciedad y suprime el apetito."])
q(64,"eosinofilos","FFV",["El nombre «leucocitos polimorfonucleares» corresponde a los neutrófilos.","Los eosinófilos son un porcentaje pequeño de los leucocitos; 25 a 33% no corresponde a ellos.","La eosinofilia aparece en alergias e infecciones parasitarias."])
q(65,"neuropeptidos-del-sueno","FFV",["«Narcoleptidos» no es un grupo de neuropéptidos reconocido como interruptor del sueño.","Las encefalinas son neuropéptidos del dolor, no interruptores del sueño.","Las orexinas actúan como interruptores del sueño y la vigilia."])
q(66,"receptores-nicotinicos","VVV",["Los receptores nicotínicos están en todas las sinapsis de los ganglios autónomos.","También están en las células de la médula suprarrenal.","La fijación de ACh a un receptor nicotínico siempre es excitatoria."])
q(67,"vias-sensitivas-de-la-medula","VFF",["La vía espinotalámica lleva dolor y temperatura; su daño explica la pérdida de ambas sensaciones.","El fascículo grácil lleva tacto fino y propiocepción.","El lemnisco medial es parte de la vía de la columna dorsal, no de dolor y temperatura."])
q(68,"membrana-timpanica","FFV",["La membrana timpánica tiene casi 1 cm de diámetro y una superficie externa un poco CÓNCAVA, no convexa (Saladin, órganos de los sentidos).","La membrana cierra el extremo INTERNO del conducto auditivo, no el externo (Saladin, órganos de los sentidos).","La membrana timpánica está inervada por ramas sensitivas de los nervios vago y trigémino y es muy sensible al dolor."])
q(69,"timo","VFF",["En adultos el timo pesa casi 20 g hasta los 60 años de edad (Saladin, sistema endocrino).","60 g no es el peso del timo adulto según el libro.","40 g no es el peso del timo adulto según el libro."])
q(70,"capas-de-la-neocorteza","FVF",["La capa I es la molecular, con pocas neuronas.","La capa IV, la granular interna, es donde se encuentran las células estrelladas.","La capa III contiene sobre todo células piramidales."])
q(71,"estados-de-refraccion","VFF",["La emetropía es el estado normal: ojo relajado y enfocado a más de 6 m.","La miopía es un defecto de refracción, no el estado normal.","La hipermetropía es un defecto de refracción, no el estado normal."])
q(72,"leucocitos-agranulocitos","VFF",["El monocito tiene citoplasma abundante con gránulos escasos y finos.","El eosinófilo tiene gránulos grandes y abundantes.","El neutrófilo tiene gránulos finos, pero su citoplasma y su núcleo multilobulado lo distinguen del monocito."])
q(73,"potencial-de-la-endolinfa","FFV",["-40 mV es el potencial del interior de la célula pilosa, no el de la endolinfa (Saladin, órganos de los sentidos).","+55 mV no es el valor que da el libro.","En relación con la perilinfa, la endolinfa tiene un potencial de casi +80 mV (Saladin, órganos de los sentidos)."],
  "Nota: el original imprime «3-80 mV» sin signo; se lee como +80 mV.")
q(74,"ondas-cerebrales-repetida","VFF",["Las ondas alfa son de 8 a 13 Hz y predominan en el área parietooccipital.","Las ondas de 14 a 30 Hz son las beta, no las zeta.","Las ondas de 4 a 7 Hz son las zeta; las beta son de 14 a 30 Hz."],
  "Nota: esta pregunta es idéntica a la 60 en el original.")
q(75,"color-de-la-luz","VFF",["El color de la luz depende de su longitud de onda.","La refracción es el cambio de dirección de la luz, no determina su color.","La velocidad no determina el color."])
q(76,"beta-oxidacion","FVF",["La β-oxidación ocurre en la matriz mitocondrial, no en la membrana.","Los ácidos grasos de cadena muy larga se metabolizan en los peroxisomas.","Los ácidos grasos de cadena corta atraviesan la membrana mitocondrial sin necesitar el sistema de la carnitina."])
q(77,"transposones","VVV",["La transposasa activa puede actuar sobre copias inactivas de transposones.","Las familias MER1, MER2 y mariner se asocian con reordenaciones cromosómicas.","En el genoma humano el gen de la transposasa suele estar mutado."])
q(78,"traduccion-en-el-ribosoma","FVF",["El segundo ARNt también necesita factores de elongación para colocarse en el sitio A.","Al terminar la translocación se liberan eEF2 y el ARNt del sitio E.","El ribosoma se desplaza en sentido 5' a 3' sobre el ARNm."])
q(79,"reticulo-endoplasmico-liso","VFF",["El REL participa en la formación de lipoproteínas, ácidos biliares y hormonas esteroideas.","El REL convierte sustancias tóxicas liposolubles en hidrosolubles, no al revés.","La glucosa 6-fosfatasa está en el lado luminal de la membrana, no en el citosólico."])
q(80,"vesiculas-revestidas","VVV",["Las vesículas de clatrina forman vesículas del Golgi destinadas a lisosomas.","Las vesículas COPII median el transporte del RER al Golgi.","Las vesículas COPI median el transporte entre cisternas del Golgi y la recuperación al RER."])
q(81,"proteinas-recombinantes","FFV",["Las bacterias no realizan splicing ni las modificaciones postraduccionales de las proteínas humanas.","Las bacterias no glucosilan proteínas.","La insulina es un ejemplo de proteína recombinante de uso clínico."])
q(82,"plegamiento-de-proteinas","FFF",["Los puentes disulfuro se forman en el retículo endoplasmático rugoso, no en el nucléolo.","La clave oficial da esta descripción como falsa.","Solo cerca de un veinte por ciento de las proteínas se pliega satisfactoriamente durante su síntesis, no el 90% (Calvo, proteínas)."])
q(83,"lisosomas","VVV",["Los lisosomas primarios se forman por gemación en la red del trans-Golgi.","En el endosoma tardío se retiran los fosfatos que marcaban las enzimas lisosómicas.","La digestión incompleta puede generar gránulos de lipofuscina."])
q(84,"senal-de-localizacion-nuclear","FFV",["Esta afirmación es correcta: la mutación en Lys-128 del antígeno T impide su entrada al núcleo.","Esta afirmación es correcta: la secuencia de localización nuclear del antígeno T tiene siete aminoácidos.","Esta es la incorrecta: las quimeras con la señal de localización nuclear se acumulan en el núcleo, no en el citoplasma."])
q(85,"arnm-y-ribosomas","FFF",["La caperuza está en el extremo 5' y la cola poli-A en el 3'; la afirmación los invierte.","Las regiones no traducidas del ARNm no se usan como patrón para la proteína.","Los ribosomas se adosan al retículo endoplasmático rugoso, no al liso."])
q(86,"elementos-repetidos-del-genoma","FFV",["La cifra que da la afirmación para nuevas inserciones Alu o L2 no es la correcta.","LINE1 es el principal componente entre los elementos nucleares dispersos largos.","Los LINE1 pueden modificar la transcripción de los genes donde se insertan."])
q(87,"fosforilacion-de-proteinas","FFF",["La adición de un grupo fosfato la catalizan las proteína quinasas, no las fosfatasas.","La eliminación del grupo fosfato la catalizan las proteína fosfatasas, no las quinasas.","Se fosforilan justamente residuos de serina, treonina, tirosina e histidina."])
q(88,"hidroxilacion-postraduccional","VVV",["La hidroxilación añade un grupo hidroxilo al anillo de una prolina (Calvo, proteínas).","La clave oficial da esta afirmación como verdadera.","La hidroxilación de prolina y lisina da estabilidad a las fibras de colágeno (Calvo, tejido conjuntivo)."],
  "Revisión pendiente: de memoria la hidroxilación de la prolina del colágeno no se considera reversible; en dos búsquedas en Calvo no se encontró la palabra «reversible» junto a hidroxilación. Se transcribe la clave oficial (D).")
q(89,"arn-polimerasas","FVF",["La ARN polimerasa I sintetiza el ARNr 28S, 18S y 5,8S en el nucléolo; el 5S lo hace la ARN polimerasa III.","La ARN polimerasa II sintetiza ARNm en el nucleoplasma.","La ARN polimerasa III sintetiza ARNt y ARNr 5S en el nucleoplasma; la afirmación atribuye a la III el 5,8S en el nucléolo."])
q(90,"carnitina-palmitoiltransferasas","FFV",["Quien transfiere el ácido graso de la acil-CoA a la carnitina es la CPT-I, no la CPT-II.","La CPT-I está en la membrana mitocondrial externa; la que cruza la membrana interna es la translocasa de acilcarnitina.","La CPT-II convierte la acilcarnitina en acil-CoA dentro de la matriz."])
q(91,"investigacion-accion","VVV",["La investigación-acción se usa cuando hay un problema que resolver.","Requiere la participación de los afectados.","Busca mejorar la calidad de la acción."],
  "Nota: esta pregunta es de Educación en Salud e Investigación; no hay libro de la gestión en el repo para contrastarla.")
q(92,"investigacion-cualitativa","FVF",["Medir variables numéricas es propio de la investigación cuantitativa.","La investigación cualitativa busca profundizar en los fenómenos estudiados.","Generalizar resultados estadísticos es propio de la investigación cuantitativa."])
q(93,"caracteristicas-de-la-investigacion-accion","FVF",["La investigación-acción no se centra en la teorización, sino en la acción para resolver el problema.","Es activa y participativa.","El problema se identifica con el grupo, no solo con el investigador."])
q(94,"muestreo-probabilistico","VFV",["En el muestreo probabilístico todos los elementos tienen una probabilidad conocida de ser seleccionados.","Se puede aplicar también en poblaciones grandes; la afirmación es falsa.","Permite extraer varias muestras distintas de una misma población."],
  "Revisión pendiente: la clave oficial marca D (las tres verdaderas), pero la afirmación 2 («solo puede aplicarse en poblaciones pequeñas») es falsa según el criterio habitual; con ella falsa, la letra sería «A o C» y no tendría respuesta única. Es de Educación en Salud e Investigación: no hay libro de la gestión en el repo.")
q(95,"unidad-de-observacion","VFV",["La unidad de observación es donde se miden las variables de interés.","No siempre coincide con la unidad de muestreo.","Puede diferir de la unidad de muestreo en algunos estudios."])
q(96,"marco-teorico-en-investigacion-narrativa","FFV",["En la investigación narrativa el marco teórico no se construye de antemano.","Esta afirmación no tiene relación con el marco teórico.","En la investigación narrativa el marco teórico se genera a partir del análisis del contenido."])
q(97,"unidad-del-estudio","VFV",["La unidad de estudio es la unidad básica que compone la población.","No siempre son personas.","Puede ser una institución, un evento o un objeto."],
  "Nota: la cartilla original marcaba B, pero la facultad publicó la corrección «A o C».")
q(98,"disenos-narrativos","FVF",["Los datos no son relatos de los investigadores.","Los diseños narrativos recolectan datos sobre historias de vida.","Los datos no son experiencias del equipo investigador."])
q(99,"fuentes-de-datos-narrativos","VVV",["Las autobiografías son una fuente de datos narrativos.","Las biografías y entrevistas son una fuente de datos narrativos.","Los testimonios de personas son una fuente de datos narrativos."])
q(100,"alcance-de-la-narracion","VFV",["La narración puede abarcar toda una historia de vida.","Un grupo de personas aisladas del grupo focal no es un alcance narrativo.","La narración puede referirse a un solo episodio."],
  "Nota: la cartilla original marcaba A, pero la facultad publicó la corrección «A o C».")
